import React, { useState, useEffect } from 'react';
import { Formik, Form, Field, getIn } from 'formik';
import * as Yup from 'yup';
import {
  TextField,
  Checkbox,
  FormControlLabel,
  Grid,
  Button,
  Box,
  Typography,
  FormHelperText,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  List,
  ListItem,
  ListItemText,
  Divider,
  Paper,
  IconButton,
  Tooltip
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import { FeatureConfig, NauthilusConfig, ServerConfig } from '../types/config';
import { useConfig } from '../contexts/ConfigContext';
import FormSection from './common/FormSection';
import CollapsibleFormSection from './common/CollapsibleFormSection';

// Built-in feature types
const builtInFeatureTypes = [
  { value: 'tls_encryption', label: 'TLS Encryption' },
  { value: 'rbl', label: 'RBL' },
  { value: 'relay_domains', label: 'Relay Domains' },
  { value: 'backend_server_monitoring', label: 'Backend Server Monitoring' },
  { value: 'brute_force', label: 'Brute Force' }
];

// Validation schema
const FeaturesConfigSchema = Yup.object().shape({
  features: Yup.array().of(
    Yup.object().shape({
      name: Yup.string().required('Feature name is required'),
    })
  ),
});

const FeaturesConfig: React.FC = () => {
  const { config, updateConfig, hasUnsavedChanges } = useConfig();

  // Initial values
  const initialValues = {
    features: config?.server?.features || [],
  };

  const handleSubmit = (values: any) => {
    // Create a properly typed copy of the config
    const updatedConfig: NauthilusConfig = { 
      ...config as NauthilusConfig,
      // Ensure server is properly initialized
      server: {
        ...(config?.server || {}) as ServerConfig,
        features: values.features
      }
    };

    updateConfig(updatedConfig);
  };

  return (
    <Box>
      <Typography variant="h4" gutterBottom>
        Features Configuration
      </Typography>

      <Formik
        initialValues={initialValues}
        validationSchema={FeaturesConfigSchema}
        onSubmit={handleSubmit}
        enableReinitialize
      >
        {({ values, errors, touched, handleChange, setFieldValue }) => (
          <Form>
            <FormSection title="Standard Features">
              <Grid container spacing={2}>
                <Grid item xs={12}>
                  <Typography variant="body1" gutterBottom>
                    Configure standard features for the server.
                  </Typography>

                  <Paper sx={{ p: 2, mb: 2 }}>
                    <List>
                      {values.features.map((feature: FeatureConfig, index: number) => (
                        <ListItem key={index} divider={index < values.features.length - 1}>
                          <Grid container spacing={2} alignItems="center">
                            <Grid item xs={10}>
                              <FormControl fullWidth error={Boolean(
                                getIn(touched, `features[${index}].name`) &&
                                getIn(errors, `features[${index}].name`)
                              )}>
                                <InputLabel id={`feature-name-label-${index}`}>Feature Type</InputLabel>
                                <Select
                                  labelId={`feature-name-label-${index}`}
                                  id={`feature-name-${index}`}
                                  name={`features[${index}].name`}
                                  value={feature.name}
                                  label="Feature Type"
                                  onChange={handleChange}
                                >
                                  {builtInFeatureTypes.map((type) => (
                                    <MenuItem key={type.value} value={type.value}>
                                      {type.label}
                                    </MenuItem>
                                  ))}
                                </Select>
                                {Boolean(
                                  getIn(touched, `features[${index}].name`) &&
                                  getIn(errors, `features[${index}].name`)
                                ) && (
                                  <FormHelperText>
                                    {getIn(errors, `features[${index}].name`)}
                                  </FormHelperText>
                                )}
                              </FormControl>
                            </Grid>
                            <Grid item xs={2}>
                              <IconButton
                                color="error"
                                onClick={() => {
                                  const newFeatures = [...values.features];
                                  newFeatures.splice(index, 1);
                                  setFieldValue('features', newFeatures);
                                }}
                              >
                                <DeleteIcon />
                              </IconButton>
                            </Grid>
                          </Grid>
                        </ListItem>
                      ))}
                    </List>

                    <Box sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
                      <Button
                        variant="outlined"
                        startIcon={<AddIcon />}
                        onClick={() => {
                          setFieldValue('features', [
                            ...values.features,
                            { name: builtInFeatureTypes[0].value },
                          ]);
                        }}
                      >
                        Add Feature
                      </Button>
                    </Box>
                  </Paper>
                </Grid>
              </Grid>
            </FormSection>


            <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end' }}>
              <Button
                type="submit"
                variant="contained"
                color="primary"
                disabled={!hasUnsavedChanges}
              >
                Save Changes
              </Button>
            </Box>
          </Form>
        )}
      </Formik>
    </Box>
  );
};

export default FeaturesConfig;
